//! A junction's `<objects>` stand along its reference line.
//!
//! `junction_objects.xodr` is generated by `scenariogeneration` (see
//! `junction_objects.py`). Junction 100's reference line is a 40 m line from
//! `(-20, -10)` heading 0.3 rad, with no elevation, so a station `(s, t)` on
//! it has a closed form.

use xodr::{
    load_file_with_provenance, Object, ObjectProvenance, Point, Provenance, RoadNetwork, Shape,
    Vector, Warning,
};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/junction_objects.xodr"
);

const HEADING: f32 = 0.3;

fn load() -> (RoadNetwork, Provenance) {
    load_file_with_provenance(FIXTURE).expect("import")
}

/// The point at `(s, t)` along junction 100's reference line.
fn station(s: f32, t: f32) -> Point {
    let (sin, cos) = HEADING.sin_cos();
    Point::new(-20.0 + s * cos - t * sin, -10.0 + s * sin + t * cos, 0.0)
}

/// Each object of junction 100 named `od_id`, with its provenance.
fn of<'a>(
    net: &'a RoadNetwork,
    prov: &'a Provenance,
    od_id: &str,
) -> Vec<(&'a Object, &'a ObjectProvenance)> {
    prov.objects
        .iter()
        .filter(|p| p.junction_id == "100" && p.od_id == od_id)
        .map(|p| (net.object(p.object).expect("baked"), p))
        .collect()
}

fn solid(object: &Object) -> (Point, f32) {
    match object.shape {
        Shape::Solid {
            position, heading, ..
        } => (position, heading),
        ref other => panic!("{} is not a solid: {other:?}", object.name),
    }
}

fn assert_near(got: Point, want: Point, what: &str) {
    assert!(
        (got - want).length() < 1e-4,
        "{what}: got {got:?}, expected {want:?}"
    );
}

#[test]
fn a_junction_object_stands_on_its_reference_line_at_its_station() {
    let (net, prov) = load();
    let [(kerb, p)] = of(&net, &prov, "j1")[..] else {
        panic!("one kerbstone");
    };
    let (position, heading) = solid(kerb);
    assert_near(position, station(10.0, 2.0) + Vector::Z * 0.1, "kerbstone");
    assert!(
        (heading - (HEADING + 0.2)).abs() < 1e-6,
        "heading {heading}"
    );
    assert_eq!((p.road_id.as_str(), p.s, p.t), ("", 10.0, 2.0));
    assert!(kerb.lanes.is_empty(), "{:?}", kerb.lanes);
}

#[test]
fn a_junction_outline_in_road_coordinates_follows_its_reference_line() {
    let (net, prov) = load();
    let [(pad, _)] = of(&net, &prov, "j2")[..] else {
        panic!("one pad");
    };
    let Shape::Outline { corners, .. } = &pad.shape else {
        panic!("an outline: {:?}", pad.shape);
    };
    let want = [(15.0, -1.0), (18.0, -1.0), (18.0, 1.0), (15.0, 1.0)];
    assert_eq!(corners.len(), want.len());
    for (c, (s, t)) in corners.iter().zip(want) {
        assert_near(c.base, station(s, t), "base");
        assert_near(c.top, station(s, t) + Vector::Z * 0.15, "top");
    }
}

#[test]
fn a_junction_repeat_steps_along_its_reference_line() {
    let (net, prov) = load();
    let bollards = of(&net, &prov, "j3");
    assert_eq!(bollards.len(), 3);
    for ((bollard, _), s) in bollards.iter().zip([20.0, 25.0, 30.0]) {
        assert_near(solid(bollard).0, station(s, -3.0), "bollard");
    }
}

#[test]
fn a_junction_object_reference_places_a_road_object_on_the_junction_line() {
    let (net, prov) = load();
    let [(post, p)] = of(&net, &prov, "post")[..] else {
        panic!("one referenced post");
    };
    assert_near(solid(post).0, station(30.0, 0.0), "post");
    assert_eq!(p.referenced_from.as_deref(), Some("1"));
}

#[test]
fn road_objects_name_no_junction_even_on_a_connecting_road() {
    let (_, prov) = load();
    let road: Vec<_> = prov
        .objects
        .iter()
        .filter(|p| !p.road_id.is_empty())
        .collect();
    let roads: Vec<&str> = road.iter().map(|p| p.road_id.as_str()).collect();
    assert_eq!(roads, ["1", "1000"]);
    assert!(road.iter().all(|p| p.junction_id.is_empty()), "{road:?}");
}

#[test]
fn junction_objects_with_no_reference_line_are_dropped_with_a_warning() {
    let (_, prov) = load();
    assert!(prov.objects.iter().all(|p| p.junction_id != "200"));
    let dropped: Vec<_> = prov
        .warnings
        .iter()
        .filter_map(|w| match w {
            Warning::JunctionObjectsDropped { junction_id } => Some(junction_id.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(dropped, ["200"]);
}

#[test]
fn a_junction_reference_line_of_any_geometry_is_baked() {
    let (net, prov) = load();
    let marker = prov
        .objects
        .iter()
        .find(|p| p.junction_id == "300")
        .expect("the marker");
    let (position, _) = solid(net.object(marker.object).unwrap());
    let hdg = 20.0_f32 / 100.0;
    let want = Point::new(100.0 + 100.0 * hdg.sin(), 100.0 * (1.0 - hdg.cos()), 0.0);
    assert_near(position, want, "marker");
}
